dashboard.definition:
{
	"title": "Executive Dashboard",
	"description": "Real-time operational awareness — IT Health, Security, Building, User Experience",
	"inputs": {
		"input_global_trp": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "global_time"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			},
			"ds.spl2": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_bldg_header": {
			"options": {
				"fontColor": "#ffb74d",
				"markdown": "## Building Resilience"
			},
			"type": "splunk.markdown"
		},
		"viz_bldg_section": {
			"options": {
				"fillColor": "#f57c00",
				"fillOpacity": 0.06,
				"rx": 10,
				"strokeColor": "#f57c00",
				"strokeOpacity": 0.3,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_bw_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**WAN Bandwidth (MFN Circuits)**"
			},
			"type": "splunk.markdown"
		},
		"viz_bw_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#0d1520",
					"#111b2b"
				]
			},
			"dataSources": {
				"primary": "ds_bandwidth"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 5,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_bw_trend": {
			"dataSources": {
				"primary": "ds_bw_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#4fc3f7",
					"#81c784",
					"#ffb74d",
					"#ef9a9a"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.line"
		},
		"viz_client_health_gauge": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 70,
						"value": "#d41f1f"
					},
					{
						"from": 70,
						"to": 85,
						"value": "#cba700"
					},
					{
						"from": 85,
						"value": "#118832"
					}
				]
			},
			"dataSources": {
				"primary": "ds_client_health_current"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 48,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%"
			},
			"type": "splunk.singlevalue"
		},
		"viz_client_health_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Client Health**"
			},
			"type": "splunk.markdown"
		},
		"viz_client_trend": {
			"dataSources": {
				"primary": "ds_client_health"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#66bb6a",
					"#ffca28",
					"#ef5350"
				],
				"stackMode": "stacked100",
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.area"
		},
		"viz_clients_donut": {
			"dataSources": {
				"primary": "ds_active_clients"
			},
			"options": {
				"backgroundColor": "transparent",
				"labelDisplay": "valuesAndPercentage",
				"seriesColors": [
					"#4fc3f7",
					"#81c784",
					"#ffb74d"
				],
				"showDonutHole": true
			},
			"type": "splunk.pie"
		},
		"viz_clients_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Active Clients**"
			},
			"type": "splunk.markdown"
		},
		"viz_clients_total": {
			"dataSources": {
				"primary": "ds_clients_total"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#ffffff",
				"majorFontSize": 42,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_clock": {
			"dataSources": {
				"primary": "ds_clock"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#546e7a",
				"majorFontSize": 14,
				"showDeltaValue": false,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_config_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Config Changes Today**"
			},
			"type": "splunk.markdown"
		},
		"viz_config_trend": {
			"dataSources": {
				"primary": "ds_config_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#4fc3f7",
					"#ef5350",
					"#ffca28"
				],
				"stackMode": "stacked",
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.column"
		},
		"viz_config_value": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 5,
						"value": "#118832"
					},
					{
						"from": 5,
						"to": 15,
						"value": "#cba700"
					},
					{
						"from": 15,
						"value": "#d41f1f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_config_changes"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 36,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_connected_label": {
			"options": {
				"fontColor": "#66bb6a",
				"fontSize": "small",
				"markdown": "**Connected**"
			},
			"type": "splunk.markdown"
		},
		"viz_connected_value": {
			"dataSources": {
				"primary": "ds_connected_count"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#66bb6a",
				"majorFontSize": 36,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_dev_health_gauge": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 70,
						"value": "#d41f1f"
					},
					{
						"from": 70,
						"to": 85,
						"value": "#cba700"
					},
					{
						"from": 85,
						"value": "#118832"
					}
				]
			},
			"dataSources": {
				"primary": "ds_device_health_current"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 48,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%"
			},
			"type": "splunk.singlevalue"
		},
		"viz_dev_health_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Device Health**"
			},
			"type": "splunk.markdown"
		},
		"viz_dns_donut": {
			"dataSources": {
				"primary": "ds_dns_categories"
			},
			"options": {
				"backgroundColor": "transparent",
				"seriesColors": [
					"#d41f1f",
					"#ef6c00",
					"#7b1fa2",
					"#cba700",
					"#546e7a"
				],
				"showDonutHole": true
			},
			"type": "splunk.pie"
		},
		"viz_dns_label": {
			"options": {
				"fontColor": "#708794",
				"fontSize": "small",
				"markdown": "DNS Blocked"
			},
			"type": "splunk.markdown"
		},
		"viz_dns_value": {
			"dataSources": {
				"primary": "ds_dns_blocked"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#ef9a9a",
				"majorFontSize": 36,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_endpoint_label": {
			"options": {
				"fontColor": "#708794",
				"fontSize": "small",
				"markdown": "Endpoint Alerts"
			},
			"type": "splunk.markdown"
		},
		"viz_endpoint_value": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 3,
						"value": "#118832"
					},
					{
						"from": 3,
						"to": 10,
						"value": "#cba700"
					},
					{
						"from": 10,
						"value": "#d41f1f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_endpoint_alerts"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 36,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_env_trend": {
			"dataSources": {
				"primary": "ds_env_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#ef5350",
					"#4fc3f7"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.line"
		},
		"viz_events_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Recent Security Events**"
			},
			"type": "splunk.markdown"
		},
		"viz_events_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#1a0808",
					"#200c0c"
				]
			},
			"dataSources": {
				"primary": "ds_security_events"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 5,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_failed_label": {
			"options": {
				"fontColor": "#708794",
				"fontSize": "small",
				"markdown": "Failed Logons"
			},
			"type": "splunk.markdown"
		},
		"viz_failed_value": {
			"dataSources": {
				"primary": "ds_failed_logons_count"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#ef9a9a",
				"majorFontSize": 36,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_footer": {
			"options": {
				"fontColor": "#37474f",
				"fontSize": "small",
				"markdown": "*Mock data — replace with live queries as data sources are onboarded. See Exec Dashboard Plan for onboarding priorities.*"
			},
			"type": "splunk.markdown"
		},
		"viz_fw_allowed": {
			"dataSources": {
				"primary": "ds_fw_allowed"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#66bb6a",
				"majorFontSize": 20,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_fw_allowed_label": {
			"options": {
				"fontColor": "#708794",
				"fontSize": "small",
				"markdown": "Allowed (24h)"
			},
			"type": "splunk.markdown"
		},
		"viz_fw_blocked": {
			"dataSources": {
				"primary": "ds_fw_blocked"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#ffffff",
				"majorFontSize": 36,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_fw_blocked_label": {
			"options": {
				"fontColor": "#708794",
				"fontSize": "small",
				"markdown": "Blocked (24h)"
			},
			"type": "splunk.markdown"
		},
		"viz_fw_top_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Top Blocked Destinations**"
			},
			"type": "splunk.markdown"
		},
		"viz_fw_top_table": {
			"context": {
				"rowBackgroundColorsByIndex": [
					"#1a0808",
					"#200c0c"
				]
			},
			"dataSources": {
				"primary": "ds_fw_top_blocked"
			},
			"options": {
				"backgroundColor": "transparent",
				"count": 5,
				"headerVisibility": "fixed",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBackgroundColorsByIndex)"
				}
			},
			"type": "splunk.table"
		},
		"viz_fw_trend": {
			"dataSources": {
				"primary": "ds_fw_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#ef5350",
					"#66bb6a"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.area"
		},
		"viz_header_bg": {
			"options": {
				"fillColor": "#080e1a",
				"fillOpacity": 1,
				"strokeWidth": 0
			},
			"type": "splunk.rectangle"
		},
		"viz_humid_gauge": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 30,
						"value": "#cba700"
					},
					{
						"from": 30,
						"to": 60,
						"value": "#118832"
					},
					{
						"from": 60,
						"value": "#cba700"
					}
				]
			},
			"dataSources": {
				"primary": "ds_humidity"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 48,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%"
			},
			"type": "splunk.singlevalue"
		},
		"viz_humid_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Humidity (%)**"
			},
			"type": "splunk.markdown"
		},
		"viz_identity_trend": {
			"dataSources": {
				"primary": "ds_identity_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#ef5350",
					"#ffca28",
					"#4fc3f7"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.line"
		},
		"viz_inv_bar": {
			"dataSources": {
				"primary": "ds_device_inventory"
			},
			"options": {
				"backgroundColor": "transparent",
				"dataValuesDisplay": "all",
				"legendDisplay": "off",
				"seriesColors": [
					"#4fc3f7"
				],
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.bar"
		},
		"viz_inv_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Device Inventory**"
			},
			"type": "splunk.markdown"
		},
		"viz_inv_total": {
			"dataSources": {
				"primary": "ds_inv_total"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "#ffffff",
				"majorFontSize": 36,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": " devices"
			},
			"type": "splunk.singlevalue"
		},
		"viz_ise_gauge": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 90,
						"value": "#d41f1f"
					},
					{
						"from": 90,
						"to": 97,
						"value": "#cba700"
					},
					{
						"from": 97,
						"value": "#118832"
					}
				]
			},
			"dataSources": {
				"primary": "ds_ise_auth"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 36,
				"showTrendIndicator": false,
				"sparklineDisplay": "off",
				"unit": "%"
			},
			"type": "splunk.singlevalue"
		},
		"viz_ise_label": {
			"options": {
				"fontColor": "#708794",
				"fontSize": "small",
				"markdown": "ISE Auth"
			},
			"type": "splunk.markdown"
		},
		"viz_ise_trend": {
			"dataSources": {
				"primary": "ds_ise_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#66bb6a",
					"#ef5350"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.area"
		},
		"viz_issue_trend": {
			"dataSources": {
				"primary": "ds_issue_trend"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendDisplay": "off",
				"seriesColors": [
					"#4fc3f7"
				],
				"xAxisLabelVisibility": "hide",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"type": "splunk.line"
		},
		"viz_issues_donut": {
			"dataSources": {
				"primary": "ds_issue_by_severity"
			},
			"options": {
				"backgroundColor": "transparent",
				"labelDisplay": "valuesAndPercentage",
				"seriesColors": [
					"#d41f1f",
					"#ef6c00",
					"#cba700"
				],
				"showDonutHole": true
			},
			"type": "splunk.pie"
		},
		"viz_issues_label": {
			"options": {
				"fontColor": "#90a4ae",
				"fontSize": "small",
				"markdown": "**Open Issues**"
			},
			"type": "splunk.markdown"
		},
		"viz_issues_value": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 10,
						"value": "#118832"
					},
					{
						"from": 10,
						"to": 25,
						"value": "#cba700"
					},
					{
						"from": 25,
						"value": "#d41f1f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_issues_current"
			},
			"options": {
				"backgroundColor": "transparent",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"majorFontSize": 48,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"type": "splunk.singlevalue"
		},
		"viz_it_header": {
			"options": {
				"fontColor": "#4fc3f7",
				"markdown": "## IT / Critical Systems Health"
			},
			"type": "splunk.markdown"
		},
		"viz_it_q": {
			"options": {
				"fontColor": "#4fc3f7",
				"fontSize": "small",
				"markdown": "*Is my infrastructure surviving?*"
			},
			"type": "splunk.markdown"
		},
		"viz_it_section": {
			"options": {
				"fillColor": "#0877a6",
				"fillOpacity": 0.08,
				"rx": 10,
				"strokeColor": "#0877a6",
				"strokeOpacity": 0.3,
				"strokeWidth": 1
			},
			"type": "splunk.rectangle"
		},
		"viz_lockouts_label": {
