	},
	"dataSources": {
		"ds_active_clients": {
			"name": "Active Clients",
			"options": {
				"query": "| makeresults | eval type=\"Wired\", count=3842 | append [| makeresults | eval type=\"Wireless\", count=12567] | append [| makeresults | eval type=\"Guest\", count=1204] | fields type count"
			},
			"type": "ds.search"
		},
		"ds_bandwidth": {
			"name": "Bandwidth by Circuit",
			"options": {
				"query": "| makeresults | eval circuit=\"Tallahassee Public\", capacity_mbps=1000, current_mbps=342, utilization=34.2 | append [| makeresults | eval circuit=\"EOC Internet\", capacity_mbps=500, current_mbps=187, utilization=37.4] | append [| makeresults | eval circuit=\"Easley\", capacity_mbps=200, current_mbps=89, utilization=44.5] | append [| makeresults | eval circuit=\"SLRC\", capacity_mbps=300, current_mbps=128, utilization=42.7] | fields circuit capacity_mbps current_mbps utilization",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_bldg_score": {
			"name": "Building Domain Score",
			"options": {
				"query": "| makeresults | eval score=74 | fields score"
			},
			"type": "ds.search"
		},
		"ds_building_occupancy": {
			"name": "Building Occupancy %",
			"options": {
				"query": "| makeresults | eval score=62 | fields score"
			},
			"type": "ds.search"
		},
		"ds_bw_trend": {
			"name": "Bandwidth Trend",
			"options": {
				"query": "| makeresults count=48 | streamstats count as i | eval _time=relative_time(now(), \"-24h\") + (i * 1800) | eval Tallahassee=round(random() % 200 + 250), EOC=round(random() % 100 + 140), Easley=round(random() % 60 + 50), SLRC=round(random() % 80 + 80) | fields _time Tallahassee EOC Easley SLRC",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_client_health": {
			"name": "Client Health Trend",
			"options": {
				"query": "| makeresults count=48 | streamstats count as i | eval _time=relative_time(now(), \"-24h\") + (i * 1800) | eval good=round(random() % 8 + 76), fair=round(random() % 5 + 12), poor=round(random() % 3 + 2) | fields _time good fair poor",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_client_health_current": {
			"name": "Client Health Current",
			"options": {
